+
+    pub(crate) async fn pick_with(
+        policy: &dyn Policy,
+        engines: &[Arc<Worker>],
+        table: &EngineLoadTable,
+        stage: RoutingStage,
+    ) -> PickResult {
+        let load = LoadView::new(table);
